<?php declare(strict_types=1); use N3\Module\Blog\BlogPost; $post = ($viewData['post'] ?? null) instanceof BlogPost ? $viewData['post'] : null; $preview = (bool) ($viewData['preview'] ?? false); ?>
<header class="site-header"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">N3</span><span>N3</span></a><?php if ($preview): ?><a href="/admin/blog/<?= $escape($post?->id ?? '') ?>/edit">Back to editor</a><?php else: ?><nav aria-label="Blog"><a href="/">Home</a><a href="/blog">Blog</a></nav><?php endif; ?></header>
<main class="public-page blog-post" id="main-content">
    <?php if ($preview): ?><div class="preview-banner" role="status"><strong>Preview:</strong> This <?= $escape($post?->status ?? '') ?> post is visible only to administrators.</div><?php endif; ?>
    <article aria-labelledby="blog-post-title"><header class="public-page-heading"><p class="eyebrow"><?= $preview ? 'Blog preview' : 'Blog' ?></p><h1 id="blog-post-title"><?= $escape($post?->title ?? '') ?></h1><?php if ($post?->publishedAt !== null): ?><p class="blog-date"><time datetime="<?= $escape(str_replace(' ', 'T', $post->publishedAt) . 'Z') ?>"><?= $escape(substr($post->publishedAt, 0, 10)) ?></time></p><?php endif; ?><?php if (($post?->excerpt ?? '') !== ''): ?><p class="page-excerpt"><?= $escape($post?->excerpt ?? '') ?></p><?php endif; ?></header><div class="page-body"><?= nl2br($escape($post?->body ?? ''), false) ?></div></article>
</main>
